      const kpis=metrics([['صافي 30 يوم',ctx.fmtMoney(perf.net||0),Number(perf.net||0)>=0?'positive':'negative'],['الودائع',ctx.fmtMoney(bank.deposits)],['القروض',ctx.fmtMoney(bank.loans)],['العملاء',ctx.fmtNumber(Number(bank.retailCustomers||0)+Number(bank.businessCustomers||0))]])+metrics([['كفاية رأس المال',pct(bank.cet1),Number(bank.cet1)>=Number(policy.minCet1)?'positive':'negative'],['القروض إلى الودائع',pct(bank.loanDepositRatio),Number(bank.loanDepositRatio)<=Number(policy.maxLdr)?'':'negative'],['السيولة LCR',pct(bank.lcr),Number(bank.lcr)>=Number(policy.minLcr)?'positive':'negative'],['التعثر',pct(bank.npl),Number(bank.npl)<=3?'':'negative']]);
      const gradeName={AA:'ممتاز',A:'جيد جدًا',BBB:'جيد',BB:'مقبول بمخاطر',B:'مرتفع المخاطر'};
      const requestCards=requests.map(q=>{const quote=core.loanRequestQuote(ctx.state,q),left=Math.max(0,Number(q.expiresDay)-today),risky=['BB','B'].includes(q.riskGrade);return `<article class="list-item bank-request-card"><div class="list-item-head"><div><h3>${ctx.esc(q.borrower)}</h3><p>${ctx.esc(quote.productName)} · ${ctx.fmtMoney(q.amount)} · <bdi dir="ltr">${quote.termYears}</bdi> ${quote.termYears>2&&quote.termYears<11?'سنوات':'سنة'} · فرع ${ctx.esc(q.branchName)}</p></div><span class="tag ${risky?'negative':'positive'}">${ctx.esc(q.riskGrade)} · ${ctx.esc(gradeName[q.riskGrade]||'')}</span></div>${metrics([['الفائدة السنوية',`${(quote.rate*100).toFixed(2)}%`],['دخل فوائد سنوي',ctx.fmtMoney(quote.annualInterest),'positive'],['الخسارة المتوقعة سنويًا',ctx.fmtMoney(quote.expectedLoss),risky?'negative':''],['الضمانات',`${Math.round(Number(q.collateralCoverage||0)*100)}%`]])}<div class="action-row">${action('bank-loan-request','موافقة ومنح التمويل',`data-request="${ctx.esc(q.id)}" data-decision="approve"`)}${action('bank-loan-request','رفض',`data-request="${ctx.esc(q.id)}" data-decision="reject"`,true)}<span class="section-mini">${left?`ينتهي الطلب بعد ${left} ${left===1?'يوم':'أيام'}`:'ينتهي اليوم'}</span></div></article>`;}).join('');
