  function notify(ctx,text,kind='info'){if(globalThis.GH_WORKFLOW?.notify)return globalThis.GH_WORKFLOW.notify(String(text||''),kind,{state:ctx.state,panel:ctx.currentPanel});ctx.pushAlert?.(String(text||''));return true;}
